260: function cleanAuthorName(authorStr) {
261:     if (!authorStr) return "";
262:     
263:     // 1. 役割や生没年を削除
264:     authorStr = authorStr.replace(/[\/／\s\[\(]*?(著|編|訳|原作|作画|原案)[\]\)]?/g, '');
265:     authorStr = authorStr.replace(/,?\s*\d{4}-?\s*/g, ' '); // remove years
266:     
267:     // 2. スラッシュ・中黒の周りのスペースを削除
268:     authorStr = authorStr.replace(/\s*([\/／・])\s*/g, "$1");
269:     
270:     // 3. 英語同士のスペースを保護 (FGO PROJECT 等)
271:     authorStr = authorStr.replace(/([A-Za-z0-9\.\-])\s+([A-Za-z0-9\.\-])/g, "$1__SPACE__$2");
272:     
273:     // 4. First Pass Last, First Merger (NDL対策)
274:     const replacer = (match, p1, p2, p3, p4) => {
275:         let last = p2;
276:         let first = p3;
277:         let kanjiMatch = last.match(/[\u4E00-\u9FFF]/g);
278:         let kanjiCount = kanjiMatch ? kanjiMatch.length : 0;
279:         if (kanjiCount <= 2 && last.length <= 4) {
280:             return p1 + last + first;
281:         }
282:         return match;
283:     };
284:     
285:     // 先読みアサーション (?=$|[\s\/／・,]) を使用して、再帰的結合を防止
286:     let regex = /(^|[\s\/／・])([\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FFA-Za-z]{1,4})\s*,\s*([\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FFA-Za-z]{1,4}[^\s,]*)(?=$|[\s\/／・,])/g;
287:     authorStr = authorStr.replace(regex, replacer);
288:     
289:     // 5. 残ったスペースと読点をカンマに変換（複数著者の区切り）
290:     authorStr = authorStr.replace(/[\s、，]+/g, ', ');
291:     
292:     // 6. 保護した英語スペースを戻す
293:     authorStr = authorStr.replace(/__SPACE__/g, ' ');
294:     
295:     // 重複カンマを整理
296:     authorStr = authorStr.replace(/(,\s*)+/g, ', ');
297:     
298:     // 7. Second Pass Last, First Merger (スペースがカンマに変わった後に再結合)
299:     authorStr = authorStr.replace(regex, replacer);
300:     
301:     // 8. 中黒・スラッシュの処理 (カタカナ・英語なら結合、漢字なら分離)
302:     let tokens = authorStr.split(/([,・\/／])/);
303:     let authors = [];
304:     let curr = "";
305:     
306:     for (let i = 0; i < tokens.length; i++) {
307:         let token = tokens[i].trim();
308:         if (!token) continue;
309:         
310:         if (token === ',') {
311:             if (curr) { authors.push(curr); curr = ""; }
312:         } else if (token === '・' || token === '/' || token === '／') {
313:             if (/[A-Za-z\u30A0-\u30FF]/.test(curr) || (i + 1 < tokens.length && /[A-Za-z\u30A0-\u30FF]/.test(tokens[i+1]))) {
314:                 curr += token;
315:             } else {
316:                 if (curr) { authors.push(curr); curr = ""; }
317:             }
318:         } else {
319:             curr += token;
320:         }
321:     }
322:     if (curr) authors.push(curr);
323:     
324:     return authors.map(a => a.trim()).filter(a => a).join(', ');
325: }
