327: function normalizeDate(dateStr) {
328:     if (!dateStr) return "";
329:     let s = dateStr.replace(/[^\d\-]/g, '');
330:     if (/^\d{8}$/.test(s)) {
331:         return `${s.substring(0,4)}-${s.substring(4,6)}-${s.substring(6,8)}`;
332:     }
333:     if (/^\d{6}$/.test(s)) {
334:         return `${s.substring(0,4)}-${s.substring(4,6)}`;
335:     }
336:     return s;
337: }
