576:             else if (displayStatus === '手放した') { bg = 'rgba(156, 163, 175, 0.2)'; color = '#d1d5db'; }    // 灰系
577:             
578:             tagsHtml += `<span class="tag" style="background: ${bg}; color: ${color};">${displayStatus}</span>`;
579:         }
580: 
581:         const summary = book.Gemini_Summary || "（要約未生成）";
582:         
583:         // 書影のURL。精度の高いAmazon(ASIN)をメインにし、失敗したらOpenBDにフォールバック
584:         const amazonUrl = getAmazonCoverUrl(book.ISBN13);
